def find_path(graph, start, goal):
    if start == goal:
        return [start]  # Start and goal are the same node

    queue = [(start, [start])]  # Queue: (current_node, path)
    visited = set()

    while queue:
        current_node, path = queue.pop(0)  # Pop the first node from the queue
        if current_node in visited:
            continue  # Skip if the node is already visited

        visited.add(current_node)  # Mark the node as visited

        if current_node == goal:
            return path  # Goal is reached, return the path

        neighbors = graph.get(current_node, [])
        if not neighbors:
            continue  # No neighbors, move to the next node

        random.shuffle(neighbors)  # Randomly shuffle the neighbors list

        for neighbor in neighbors:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))  # Add to the queue

    return None  # Goal is unreachable

