import math

def find_path(graph, start, goal):
    # Total number of nodes in the graph
    total_nodes = len(graph)

    # Calculate the number of jumps (integer part of the square root of the total nodes)
    num_jumps = int(math.sqrt(total_nodes))

    # Function to make a jump from current node to target node
    def jump_search(current_node, target_node, jumps, path, visited_nodes):
        if current_node == target_node:
            return path

        # Mark the current node as visited
        visited_nodes.add(current_node)

        # Explore nodes in the current jump
        for node in graph.get(current_node, []):
            if node not in visited_nodes:
                path.append(node)
                if node == target_node:
                    return path
                new_path = jump_search(node, target_node, jumps-1, path, visited_nodes)
                if new_path:
                    return new_path

            # If we hit the end of the jump, start a smaller jump
            if node not in graph:
                new_path = jump_search(node, target_node, jumps-1, path, visited_nodes)
                if new_path:
                    return new_path

    # Start the jump search
    if start not in graph:
        return None

    path = []
    visited_nodes = set()
    path.append(start)

    # Initial jump search
    for i in range(num_jumps):
        new_path = jump_search(start, goal, num_jumps-i, path, visited_nodes)
        if new_path:
            return new_path

    # If no path is found, return None
    return None

