def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Function to perform BFS and find a path that minimizes the number of edges
    def bfs(graph, start, goal):
        visited = {start}
        queue = deque([(start, [start])])  # (current node, path taken)

        while queue:
            current, path = queue.popleft()
            if current == goal:
                return path
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))

        return None

    # Function to perform Dijkstra's algorithm to find the shortest path with respect to edge weights
    def dijkstra(graph, start, goal):
        pq = [(0, start)]  # (cost, node)
        visited = {start}
        parent = {start: None}  # Tracks the parent of each node to reconstruct the path
        while pq:
            cost, current = heapq.heappop(pq)
            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = parent[current]
                return path[::-1]
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    heapq.heappush(pq, (cost + graph[current][neighbor], neighbor))
                    parent[neighbor] = current

        return None

    # Perform BFS to get a path that minimizes the number of edges
    bfs_path = bfs(graph, start, goal)

    if bfs_path is None:
        return None  # No path found with BFS, which means the goal is unreachable from the start

    # Optionally apply Dijkstra's algorithm to find the optimal path with respect to edge weights
    optimal_path = dijkstra(graph, start, goal) if bfs_path else None

    # Return the optimal path found
    return bfs_path if optimal_path is None else optimal_path

